

import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from .chat_completion_message_tool_calls import ChatCompletionMessageToolCalls
from .chat_completion_request_assistant_message_function_call import ChatCompletionRequestAssistantMessageFunctionCall


class ChatCompletionRequestAssistantMessage(UniversalBaseModel):
    content: typing.Optional[str] = pydantic.Field(default=None)
    """
    The contents of the assistant message. Required unless `tool_calls` or `function_call` is specified.
    """

    name: typing.Optional[str] = pydantic.Field(default=None)
    """
    An optional name for the participant. Provides the model information to differentiate between participants of the same role.
    """

    tool_calls: typing.Optional[ChatCompletionMessageToolCalls] = None
    function_call: typing.Optional[ChatCompletionRequestAssistantMessageFunctionCall] = pydantic.Field(default=None)
    """
    Deprecated and replaced by `tool_calls`. The name and arguments of a function that should be called, as generated by the model.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
